    if (document.getElementById('sl-system-event-notice')) return;
    const panel = document.createElement('aside'); panel.id = 'sl-system-event-notice'; panel.className = 'sl-system-event-notice'; panel.setAttribute('aria-live', 'assertive'); panel.setAttribute('aria-atomic', 'true');
    panel.innerHTML = `<span class="sl-event-corner corner-a"></span><span class="sl-event-corner corner-b"></span><span class="sl-event-corner corner-c"></span><span class="sl-event-corner corner-d"></span><header data-sl-event-drag><span class="sl-event-brand"><b>SYS</b><span>EVENT RECORD</span></span><span class="sl-event-queue">01</span><i class="fa-solid fa-grip-lines sl-event-drag-icon"></i></header><button class="sl-event-body" type="button" data-sl-event-arm><span class="sl-event-alarm"><i class="fa-solid fa-exclamation"></i><b data-sl-event-label>SYSTEM ALERT</b></span><strong data-sl-event-title>SYSTEM UPDATED</strong><small data-sl-event-detail>The System has detected a confirmed change.</small><em>${t('notification_tap')}</em></button><footer><button type="button" data-sl-event-open><i class="fa-solid fa-arrow-up-right-from-square"></i> ${t('notification_view')}</button><button type="button" data-sl-event-dismiss><i class="fa-solid fa-xmark"></i> ${t('notification_remove')}</button></footer><span class="sl-event-scan"></span>`;
    panel.querySelector('[data-sl-event-arm]')?.addEventListener('click', () => { eventNoticeDismissArmed = !eventNoticeDismissArmed; panel.classList.toggle('is-armed', eventNoticeDismissArmed); });
    panel.querySelector('[data-sl-event-open]')?.addEventListener('click', () => { if (eventNoticeCurrent?.destination) navigateNotice(eventNoticeCurrent.destination); eventNoticeDismissArmed = false; panel.classList.remove('is-armed'); });
    panel.querySelector('[data-sl-event-dismiss]')?.addEventListener('click', dismissEventNotice);
    document.body.appendChild(panel); bindEventNoticeDrag(panel); positionEventNotice();
